<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$permissionGroups=[];foreach($permissions as $p)$permissionGroups[explode('.',$p['slug'])[0]][]=$p;?>
<div class="space-y-6" x-data="groupsPage(<?=htmlspecialchars(json_encode($groups,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT),ENT_QUOTES,'UTF-8')?>)"><header class="flex justify-between items-end"><div><h1 class="text-3xl font-bold">Grupos de seguridad</h1><p class="text-slate-400 mt-1">Roles, acceso administrativo, revendedores y permisos detallados.</p></div><button @click="create" class="bg-blue-700 px-4 py-2 rounded">Añadir grupo</button></header><section class="grid grid-cols-2 md:grid-cols-4 gap-3"><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><span class="text-xs text-slate-500">GRUPOS</span><strong class="block text-2xl"><?=count($groups)?></strong></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><span class="text-xs text-slate-500">ADMINISTRATIVOS</span><strong class="block text-2xl text-blue-400"><?=count(array_filter($groups,fn($g)=>(int)$g['is_admin']===1))?></strong></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><span class="text-xs text-slate-500">REVENDEDORES</span><strong class="block text-2xl text-blue-400"><?=count(array_filter($groups,fn($g)=>(int)$g['is_reseller']===1))?></strong></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><span class="text-xs text-slate-500">MIEMBROS</span><strong class="block text-2xl"><?=array_sum(array_column($groups,'members'))?></strong></div></section>
<div class="overflow-x-auto border border-slate-800 rounded-xl"><table class="w-full text-sm"><thead class="bg-slate-900 text-slate-400 uppercase text-xs"><tr><th class="p-4 text-left">Grupo</th><th>Administrador</th><th>Revendedor</th><th>Subrevendedores</th><th>Permisos</th><th>Miembros</th><th class="p-4 text-right">Acciones</th></tr></thead><tbody class="divide-y divide-slate-800"><?php foreach($groups as $g):?><tr class="hover:bg-slate-900/50"><td class="p-4"><strong><?=$e($g['name'])?></strong><div class="text-xs text-slate-500"><?=$e($g['description']?:$g['slug'])?></div></td><?php foreach(['is_admin','is_reseller','allows_subresellers'] as $flag):?><td class="text-center"><span class="inline-block w-3 h-3 rounded-full <?=$g[$flag]?'bg-blue-500':'bg-slate-700'?>"></span></td><?php endforeach?><td class="text-center"><?=count($g['permission_ids'])?></td><td class="text-center"><?=$g['members']?></td><td class="p-3"><div class="flex justify-end gap-2"><?php if(!$g['system_locked']):?><button @click="edit(<?=$g['id']?>)" class="bg-slate-700 px-3 py-1.5 rounded">Editar</button><form method="post" action="/security/groups/delete" onsubmit="return confirm('¿Eliminar este grupo?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$g['id']?>"><button class="bg-red-900 px-3 py-1.5 rounded">Eliminar</button></form><?php else:?><span class="text-xs text-blue-400">Protegido</span><?php endif?></div></td></tr><?php endforeach?></tbody></table></div>
<div x-show="open" x-cloak style="display:none" class="relative bg-black/80 z-50 grid place-items-center p-4"><form method="post" action="/security/groups" @click.outside="open=false" class="bg-slate-950 border border-blue-900 rounded-2xl p-6 w-full max-w-5xl max-h-[92vh] overflow-y-auto"><?=$csrf->field()?><input type="hidden" name="id" :value="form.id"><div class="flex justify-between"><h2 class="text-2xl font-bold" x-text="form.id?'Editar grupo':'Nuevo grupo'"></h2><button type="button" @click="open=false">✕</button></div><div class="grid md:grid-cols-2 gap-4 mt-5"><label>Nombre<input required minlength="2" maxlength="100" name="name" x-model="form.name" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Descripción<input maxlength="255" name="description" x-model="form.description" class="w-full bg-slate-800 p-2 rounded mt-1"></label></div><div class="flex flex-wrap gap-6 bg-slate-900 p-4 rounded-xl mt-4"><label><input type="checkbox" name="is_admin" x-model="form.is_admin" @change="if(form.is_admin)form.is_reseller=false"> Grupo administrativo</label><label><input type="checkbox" name="is_reseller" x-model="form.is_reseller" @change="if(form.is_reseller)form.is_admin=false"> Grupo revendedor</label><label :class="form.is_reseller?'':'opacity-40'"><input type="checkbox" name="allows_subresellers" x-model="form.allows_subresellers" :disabled="!form.is_reseller"> Puede crear subrevendedores</label></div><h3 class="font-bold mt-6">Permisos individuales</h3><p class="text-sm text-slate-400">Selecciona únicamente lo que este grupo necesita.</p><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4 mt-3"><?php foreach($permissionGroups as $area=>$items):?><fieldset class="bg-slate-900 border border-slate-800 rounded-xl p-4"><legend class="px-2 font-semibold uppercase text-xs text-blue-400"><?=$e($area)?></legend><div class="space-y-2"><?php foreach($items as $p):?><label class="flex gap-2 items-start"><input type="checkbox" name="permission_ids[]" value="<?=$p['id']?>" :checked="form.permission_ids.includes(<?=$p['id']?>)"><span><?=$e($p['name'])?><small class="block text-slate-500"><?=$e($p['slug'])?></small></span></label><?php endforeach?></div></fieldset><?php endforeach?></div><div class="flex justify-end gap-3 mt-6"><button type="button" @click="open=false" class="bg-slate-700 px-5 py-2 rounded">Cancelar</button><button class="bg-blue-700 px-5 py-2 rounded">Guardar grupo</button></div></form></div></div>
<script>function groupsPage(groups){return{groups,open:false,form:{},create(){this.form={id:'',name:'',description:'',is_admin:false,is_reseller:false,allows_subresellers:false,permission_ids:[]};this.open=true},edit(id){let g=this.groups.find(x=>Number(x.id)===id);this.form={id:g.id,name:g.name,description:g.description||'',is_admin:Boolean(Number(g.is_admin)),is_reseller:Boolean(Number(g.is_reseller)),allows_subresellers:Boolean(Number(g.allows_subresellers)),permission_ids:(g.permission_ids||[]).map(Number)};this.open=true}}}</script>
